"use client";

import { useId, useState, type ComponentPropsWithoutRef } from "react";

import { useThemeWipe } from "./use-theme-wipe";
import { ThemeToggleVariants, type Theme } from "./theme-toggle-variants";

export type ThemeToggleMode = "light" | "dark";

export interface ThemeToggleProps extends Omit<
  ComponentPropsWithoutRef<"button">,
  "children"
> {
  variant?: "icon" | "pill" | "segmented";
  onValueChange?: (theme: Theme) => void;
  storageKey?: string;
  attribute?: "class" | "data-theme";
  reveal?: boolean;
  theme?: ThemeToggleMode;
  defaultTheme?: ThemeToggleMode;
  onThemeChange?: (theme: ThemeToggleMode) => void;
  size?: number;
  /** Opt in to a document reveal. onThemeChange must apply the theme synchronously. */
  pageTransition?: "none" | "circular";
}

const morph =
  "origin-center [transform-box:view-box] transition-[transform,opacity] duration-[420ms] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none";

function LegacyThemeToggle({
  theme,
  defaultTheme = "light",
  onThemeChange,
  size = 48,
  pageTransition = "none",
  disabled,
  className = "",
  style,
  onClick,
  type = "button",
  "aria-label": label,
  ...props
}: ThemeToggleProps) {
  const [localTheme, setLocalTheme] = useState(defaultTheme);
  const currentTheme = theme ?? localTheme;
  const wipe = useThemeWipe();
  const dark = currentTheme === "dark";
  const maskId = `theme-toggle-${useId().replaceAll(":", "")}`;

  return (
    <button
      {...props}
      type={type}
      disabled={disabled}
      aria-label={label ?? `Switch to ${dark ? "light" : "dark"} mode`}
      aria-pressed={dark}
      data-theme-toggle={currentTheme}
      className={`inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full border-0 bg-white p-0 text-black transition-[background-color,color,scale] duration-200 hover:scale-[1.04] active:scale-95 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:scale-100 data-[theme-toggle=dark]:bg-black data-[theme-toggle=dark]:text-white motion-reduce:transition-none motion-reduce:hover:scale-100 motion-reduce:active:scale-100 ${pageTransition === "circular" ? "hover:scale-100! active:scale-100!" : ""} ${className}`}
      style={{
        width: size,
        height: size,
        minWidth: 44,
        minHeight: 44,
        ...style,
      }}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        wipe(
          event.currentTarget,
          currentTheme,
          pageTransition,
          (next) => {
            if (theme === undefined) setLocalTheme(next);
            onThemeChange?.(next);
          },
          props.nonce,
        );
      }}
    >
      <svg
        aria-hidden="true"
        focusable="false"
        viewBox="0 0 32 32"
        className="size-2/3 overflow-visible"
      >
        <defs>
          <mask
            id={maskId}
            maskUnits="userSpaceOnUse"
            x="0"
            y="0"
            width="32"
            height="32"
          >
            <rect width="32" height="32" fill="white" />
            <circle
              data-theme-toggle-cutout=""
              cx="36"
              cy="-4"
              r="8"
              fill="black"
              className={morph}
              style={{
                transform: dark
                  ? "translate(-16px, 16px)"
                  : "translate(0px, 0px)",
              }}
            />
          </mask>
        </defs>
        <g mask={`url(#${maskId})`}>
          <circle
            cx="16"
            cy="16"
            r="7.5"
            fill="currentColor"
            className={morph}
            style={{ transform: dark ? "scale(1.2)" : "scale(1)" }}
          />
        </g>
        <g
          data-theme-toggle-rays=""
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
          className={morph}
          style={{
            opacity: dark ? 0 : 1,
            transform: dark
              ? "rotate(45deg) scale(0.5)"
              : "rotate(0deg) scale(1)",
          }}
        >
          {Array.from({ length: 8 }, (_, index) => (
            <line
              key={index}
              x1="16"
              y1="2"
              x2="16"
              y2="6"
              transform={`rotate(${index * 45} 16 16)`}
            />
          ))}
        </g>
      </svg>
    </button>
  );
}

export function ThemeToggle(props: ThemeToggleProps) {
  if (
    props.variant !== undefined ||
    props.onValueChange ||
    props.storageKey ||
    props.attribute ||
    props.reveal !== undefined
  ) {
    const choice = (value: unknown): Theme | undefined =>
      value === "light" || value === "dark" || value === "system"
        ? value
        : undefined;
    return (
      <ThemeToggleVariants
        variant={props.variant}
        value={choice(props.value)}
        defaultValue={choice(props.defaultValue)}
        onValueChange={props.onValueChange}
        storageKey={props.storageKey}
        attribute={props.attribute}
        reveal={props.reveal}
        className={props.className}
        style={props.style}
        id={props.id}
      />
    );
  }
  return <LegacyThemeToggle {...props} />;
}

"use client";

import { useEffect, useRef } from "react";
import { flushSync } from "react-dom";

type Mode = "light" | "dark";
type ActiveWipe = { mode: Mode; cancel: () => void };

// A document can have only one view transition, even with several toggles.
const activeWipes = new WeakMap<Document, ActiveWipe>();
const styles = `
html[data-theme-wipe]::view-transition { pointer-events: none; }
html[data-theme-wipe]::view-transition-group(*) { animation: none; }
html[data-theme-wipe]::view-transition-old(root),
html[data-theme-wipe]::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}`;

export function useThemeWipe() {
  const owned = useRef<ActiveWipe | null>(null);
  useEffect(() => () => owned.current?.cancel(), []);

  return (
    origin: HTMLElement,
    current: Mode,
    effect: "none" | "circular",
    change: (mode: Mode) => void,
    nonce?: string,
  ) => {
    const doc = origin.ownerDocument;
    const win = doc.defaultView;
    const previous = activeWipes.get(doc);
    const mode = (previous?.mode ?? current) === "dark" ? "light" : "dark";
    previous?.cancel();
    let applied = false;
    const apply = () => {
      if (applied) return;
      applied = true;
      flushSync(() => change(mode));
    };
    const reduced = win?.matchMedia("(prefers-reduced-motion: reduce)");
    if (
      effect === "none" ||
      previous ||
      !win ||
      reduced?.matches ||
      doc.visibilityState === "hidden" ||
      !doc.startViewTransition ||
      // Do not interrupt a router-owned transition on browsers exposing it.
      (doc as Document & { activeViewTransition?: ViewTransition | null })
        .activeViewTransition
    ) {
      apply();
      return;
    }

    const root = doc.documentElement;
    const bounds = origin.getBoundingClientRect();
    const x = bounds.left + bounds.width / 2;
    const y = bounds.top + bounds.height / 2;
    const radius = Math.hypot(
      Math.max(x, win.innerWidth - x),
      Math.max(y, win.innerHeight - y),
    );
    // Ship scoped transition CSS with the helper, not the app's stylesheet.
    const sheet = doc.createElement("style");
    if (nonce) sheet.nonce = nonce;
    sheet.textContent = styles;
    doc.head.append(sheet);
    if (!sheet.sheet) {
      sheet.remove();
      apply();
      return;
    }
    const oldAttribute = root.getAttribute("data-theme-wipe");
    let cancelled = false;
    let transition: ViewTransition | undefined;
    let animation: Animation | undefined;
    const cleanup = () => {
      animation?.cancel();
      sheet.remove();
      reduced?.removeEventListener("change", settle);
      win.removeEventListener("resize", settle);
      doc.removeEventListener("visibilitychange", visibility);
      if (activeWipes.get(doc) === run) {
        activeWipes.delete(doc);
        if (oldAttribute === null) root.removeAttribute("data-theme-wipe");
        else root.setAttribute("data-theme-wipe", oldAttribute);
      }
      if (owned.current === run) owned.current = null;
    };
    const run: ActiveWipe = {
      mode,
      cancel() {
        cancelled = true;
        transition?.skipTransition();
        cleanup();
      },
    };
    function settle() {
      run.cancel();
      apply();
    }
    function visibility() {
      if (doc.visibilityState === "hidden") settle();
    }
    owned.current = run;
    activeWipes.set(doc, run);
    root.setAttribute("data-theme-wipe", "");
    reduced?.addEventListener("change", settle);
    win.addEventListener("resize", settle);
    doc.addEventListener("visibilitychange", visibility);

    try {
      transition = doc.startViewTransition(() => {
        if (!cancelled) apply();
      });
      if (cancelled) transition.skipTransition();
      void transition.ready
        .then(() => {
          if (cancelled) return;
          animation = root.animate(
            {
              clipPath: [
                `circle(0px at ${x}px ${y}px)`,
                `circle(${radius}px at ${x}px ${y}px)`,
              ],
            },
            {
              duration: 620,
              easing: "cubic-bezier(0.65, 0, 0.35, 1)",
              pseudoElement: "::view-transition-new(root)",
            },
          );
        })
        .catch(() => {
          if (!cancelled) settle();
        });
      void transition.finished.then(cleanup, cleanup);
    } catch {
      settle();
    }
  };
}

"use client";

import * as React from "react";
import { flushSync } from "react-dom";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * THEME TOGGLE: the sun sets into a moon, and the room follows
 *
 *   icon       one round button: the sun's rays fold in and turn
 *              away while a shadow slides across the disc and
 *              carves the moon (and back at dawn)
 *   pill       the same icon with a label that morphs, "Light"
 *              into "Dark"
 *   segmented  Light, System and Dark, with a thumb thrown to the
 *              choice; its icon morphs the same way
 *   reveal     the new theme spreads out from the button in a
 *              circle (View Transitions); elsewhere it switches
 *              without a flash of animated colours
 *
 * On its own it remembers the choice, follows the system when
 * asked to and sets the dark class on <html>. Pass value and
 * onValueChange to drive it from next-themes or your own state.
 * ───────────────────────────────────────────────────────── */

export type Theme = "light" | "dark" | "system";

export interface ThemeToggleVariantsProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  variant?: "icon" | "pill" | "segmented";
  value?: Theme;
  defaultValue?: Theme;
  onValueChange?: (theme: Theme) => void;
  /** Where an uncontrolled toggle remembers the choice. */
  storageKey?: string;
  /** How an uncontrolled toggle marks dark mode on <html>: the "dark" class, or data-theme. */
  attribute?: "class" | "data-theme";
  /** Spread the new theme from the button in a circle, where the browser can. */
  reveal?: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";
const OPTIONS: { value: Theme; label: string }[] = [
  { value: "light", label: "Light" },
  { value: "system", label: "System" },
  { value: "dark", label: "Dark" },
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const darkQuery = "(prefers-color-scheme: dark)";
const subscribeQuery = (q: string) => (onChange: () => void) => {
  const query = window.matchMedia(q);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useMedia = (q: string) =>
  React.useSyncExternalStore(
    subscribeQuery(q),
    () => window.matchMedia(q).matches,
    () => false,
  );

/**
 * The sun and moon are one drawing: a disc that grows into the moon, eight rays that fold in,
 * and a shadow (a masked-out circle) that slides across to carve the crescent.
 */
function SunMoon({
  dark,
  reduced,
  className = "size-[18px]",
}: {
  dark: boolean;
  reduced: boolean;
  className?: string;
}) {
  const id = React.useId().replace(/:/g, "");
  const t = (ms: number, ease = EASE) =>
    reduced
      ? "none"
      : `transform ${ms}ms ${ease}, opacity ${Math.round(ms * 0.6)}ms ${EASE}`;
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 24 24"
      fill="none"
      className={className}
    >
      <mask id={`${id}-shadow`}>
        <rect width="24" height="24" fill="white" />
        <circle
          cx="12"
          cy="12"
          r="8"
          fill="black"
          style={{
            transform: dark ? "translate(5px,-5px)" : "translate(14px,-14px)",
            transition: t(560),
          }}
        />
      </mask>
      <circle
        cx="12"
        cy="12"
        r="8"
        fill="currentColor"
        mask={`url(#${id}-shadow)`}
        style={{
          transformOrigin: "12px 12px",
          transform: dark ? "scale(1.05)" : "scale(0.55)",
          transition: t(560, THROW),
        }}
      />
      <g
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        style={{
          transformOrigin: "12px 12px",
          transform: dark ? "rotate(-90deg) scale(0.4)" : "none",
          opacity: dark ? 0 : 1,
          transition: t(520),
        }}
      >
        {[0, 45, 90, 135, 180, 225, 270, 315].map((a) => (
          <line
            key={a}
            x1="12"
            y1="2.5"
            x2="12"
            y2="4.5"
            transform={`rotate(${a} 12 12)`}
          />
        ))}
      </g>
    </svg>
  );
}

function SystemIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" className="size-4">
      <rect
        x="3"
        y="4.5"
        width="18"
        height="12.5"
        rx="2.5"
        stroke="currentColor"
        strokeWidth="1.7"
      />
      <path
        d="M9 20.5h6M12 17v3.5"
        stroke="currentColor"
        strokeWidth="1.7"
        strokeLinecap="round"
      />
    </svg>
  );
}

/** Switch themes inside a View Transition, revealed as a circle growing out of the button. */
function withReveal(
  from: HTMLElement | null,
  apply: () => void,
  enabled: boolean,
) {
  const doc = document as Document & {
    startViewTransition?: (cb: () => void) => {
      ready: Promise<void>;
      finished: Promise<void>;
    };
  };
  if (!enabled || !from || !doc.startViewTransition) {
    // No transition API: switch with colour transitions held for a frame, so nothing flickers mid-change.
    const hold = document.createElement("style");
    hold.textContent = "*,*::before,*::after{transition:none!important}";
    document.head.appendChild(hold);
    apply();
    void document.body.offsetHeight;
    requestAnimationFrame(() => hold.remove());
    return;
  }
  const r = from.getBoundingClientRect();
  const x = r.left + r.width / 2;
  const y = r.top + r.height / 2;
  const radius = Math.hypot(
    Math.max(x, innerWidth - x),
    Math.max(y, innerHeight - y),
  );
  // Only the circle should move: switch off the browser's default crossfade for this one transition.
  const style = document.createElement("style");
  style.textContent =
    "::view-transition-old(root),::view-transition-new(root){animation:none;mix-blend-mode:normal}";
  document.head.appendChild(style);
  const transition = doc.startViewTransition(() => flushSync(apply));
  transition.ready
    .then(() =>
      document.documentElement.animate(
        {
          clipPath: [
            `circle(0px at ${x}px ${y}px)`,
            `circle(${radius}px at ${x}px ${y}px)`,
          ],
        },
        {
          duration: 620,
          easing: "cubic-bezier(0.65,0,0.35,1)",
          pseudoElement: "::view-transition-new(root)",
        },
      ),
    )
    .catch(() => {});
  transition.finished.finally(() => style.remove());
}

/** The choice saved in this browser, read straight from localStorage (and kept in step with other tabs). */
const subscribeSaved = (onChange: () => void) => {
  window.addEventListener("storage", onChange);
  return () => window.removeEventListener("storage", onChange);
};
const readSaved = (key: string): Theme | null => {
  try {
    const saved = localStorage.getItem(key);
    return saved === "light" || saved === "dark" || saved === "system"
      ? saved
      : null;
  } catch {
    return null;
  }
};

export function ThemeToggleVariants({
  variant = "icon",
  value,
  defaultValue = "system",
  onValueChange,
  storageKey = "theme",
  attribute = "class",
  reveal = true,
  className = "",
  ...props
}: ThemeToggleVariantsProps) {
  const reduced = useMedia(reducedQuery);
  const systemDark = useMedia(darkQuery);
  const controlled = value !== undefined;
  // Uncontrolled: what was picked here, else what this browser saved, else the default. The server and the first paint
  // use the default, and the saved choice lands right after hydration (the first paint never animates).
  const saved = React.useSyncExternalStore(
    subscribeSaved,
    () => readSaved(storageKey),
    () => null,
  );
  const [picked, setPicked] = React.useState<Theme | null>(null);
  const [ready, setReady] = React.useState(false);
  const theme = value ?? picked ?? saved ?? defaultValue;
  const resolved = theme === "system" ? (systemDark ? "dark" : "light") : theme;
  const dark = resolved === "dark";
  const rootRef = React.useRef<HTMLDivElement>(null);
  const segRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [thumb, setThumb] = React.useState({ left: 0, width: 0, ready: false });

  // Motion starts a frame after mount, so restoring a saved choice never animates.
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setReady(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  // Uncontrolled: mark <html> and follow the system while on "system".
  React.useEffect(() => {
    if (controlled) return;
    const root = document.documentElement;
    if (attribute === "class") root.classList.toggle("dark", dark);
    else root.setAttribute("data-theme", resolved);
    root.style.colorScheme = resolved;
  }, [controlled, dark, resolved, attribute]);

  const choose = (next: Theme) => {
    if (next === theme) return;
    const nextDark =
      (next === "system" ? systemDark : next === "dark") !== dark;
    const apply = () => {
      if (!controlled) {
        setPicked(next);
        try {
          localStorage.setItem(storageKey, next);
        } catch {}
        const root = document.documentElement;
        const r = next === "system" ? (systemDark ? "dark" : "light") : next;
        if (attribute === "class") root.classList.toggle("dark", r === "dark");
        else root.setAttribute("data-theme", r);
        root.style.colorScheme = r;
      }
      onValueChange?.(next);
    };
    // Only reveal when the colours actually change (System to Light on a light system doesn't).
    withReveal(rootRef.current, apply, reveal && !reduced && nextDark);
  };

  // Segmented: the thumb sits under the choice.
  const index = Math.max(
    0,
    OPTIONS.findIndex((o) => o.value === theme),
  );
  React.useLayoutEffect(() => {
    if (variant !== "segmented") return;
    const measure = () => {
      const el = segRefs.current[index];
      if (!el) return;
      setThumb((t) =>
        t.left === el.offsetLeft && t.width === el.offsetWidth
          ? t
          : { left: el.offsetLeft, width: el.offsetWidth, ready: t.width > 0 },
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    segRefs.current.forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [variant, index]);

  const motion = reduced || !ready;
  const label = dark ? "Dark" : "Light";

  if (variant === "segmented") {
    return (
      <div
        ref={rootRef}
        role="radiogroup"
        aria-label="Theme"
        onKeyDown={(e) => {
          const moves: Record<string, number> = {
            ArrowRight: index + 1,
            ArrowLeft: index - 1,
            Home: 0,
            End: OPTIONS.length - 1,
          };
          if (!(e.key in moves)) return;
          e.preventDefault();
          const next = (moves[e.key] + OPTIONS.length) % OPTIONS.length;
          choose(OPTIONS[next].value);
          segRefs.current[next]?.focus();
        }}
        className={`relative inline-flex h-9 items-center rounded-full bg-muted p-0.5 ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
          style={{
            width: thumb.width,
            transform: `translateX(${thumb.left}px)`,
            opacity: thumb.width ? 1 : 0,
            transition:
              thumb.ready && !reduced
                ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                : "none",
          }}
        />
        {OPTIONS.map((o, i) => {
          const selected = o.value === theme;
          return (
            <button
              key={o.value}
              ref={(el) => {
                segRefs.current[i] = el;
              }}
              type="button"
              role="radio"
              aria-checked={selected}
              aria-label={o.label}
              tabIndex={selected ? 0 : -1}
              onClick={() => choose(o.value)}
              className={`cursor-pointer relative flex h-8 w-10 items-center justify-center rounded-full transition-colors duration-300 ${FOCUS} ${selected ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
            >
              {o.value === "system" ? (
                <SystemIcon />
              ) : (
                <SunMoon
                  dark={o.value === "dark"}
                  reduced={motion}
                  className="size-4"
                />
              )}
            </button>
          );
        })}
      </div>
    );
  }

  return (
    <div ref={rootRef} className={`inline-flex ${className}`} {...props}>
      <button
        type="button"
        // The pill's name starts with the word it shows, so voice control can say it.
        aria-label={
          variant === "pill"
            ? `${label} theme, switch to ${dark ? "light" : "dark"}`
            : `Switch to ${dark ? "light" : "dark"} theme`
        }
        aria-pressed={dark}
        onClick={() => choose(dark ? "light" : "dark")}
        className={`cursor-pointer inline-flex h-9 items-center justify-center rounded-full text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-[background-color,box-shadow] duration-300 hover:bg-accent active:scale-[0.96] ${FOCUS} ${
          variant === "pill"
            ? "gap-2 pl-2.5 pr-3.5 text-[13px] font-medium"
            : "w-9"
        }`}
      >
        <SunMoon dark={dark} reduced={motion} />
        {variant === "pill" && <TextMorph>{label}</TextMorph>}
      </button>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

